def guard():
 files=[*ENGINE.glob('*.py'),*ENGINE.glob('*.json'),*(p for p in(ENGINE/'references').rglob('*')if p.is_file())]
 if {str(p.relative_to(ENGINE))for p in files}!=set(PINS):raise ValueError('SOURCE_SET_CHANGED')
